head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > deleteRowss]<br/>인덱스값의 배열을 사용하여 한 개 이상의 Row 상태값을 '삭제' 로 변경한 후 '삭제' 상태인 Row 들의 데이터를 2차원 배열로 반환합니다.",
    "validation" : [
        "Row 의 인덱스는 0 부터 시작하며 필터가 적용된 경우 필터링된 Row 를 기준으로 인덱스를 설정합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');
}



scwin.btn_deleteRows_onclick = function (e) {
    let rowIndexArray = par_rowIndexArray.getText();
    let rtn = '';

    if (rowIndexArray == "")
        rtn = target1.deleteRows();
    else
        rtn = target1.deleteRows(eval(rowIndexArray));

    for (var i=0; i < rtn.length; i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("result["+i+"]: " + rtn[i]);
    } 
};



scwin.btn_setColumnFilter_onclick = function (e) {
	target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_2", condition:'and'})
    target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_4", condition:'or'})
};
